 badminton:'M8 16 3 5l4-3 6 1 7 4-9 12M3 5l8 10M7 2l5 13m1-12 1 11m6-7-6 8M8 16l3 3m-3-3a3 3 0 1 0 3 3',
 yoga:'M12 7a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5ZM9 10l-3 5H2m13-5 3 5h4m-10-5v6m0 0-6 2q-4 2 0 3h12q4-1 0-3l-6-2m-4 5 8-3',
